reference_solution:
def valid_utf8(data):
    remaining = 0
    for value in data:
        if remaining:
            if value & 0xC0 != 0x80:
                return False
            remaining -= 1
        elif value < 128:
            continue
        elif value & 0xE0 == 0xC0:
            remaining = 1
        elif value & 0xF0 == 0xE0:
            remaining = 2
        elif value & 0xF8 == 0xF0:
            remaining = 3
        else:
            return False
    return remaining == 0

